#define MATRIX_SIZE 512
int M[MATRIX_SIZE][MATRIX_SIZE]; // L1/L2 Cache (SRAM) access

// SCENARIO 1: HIGH SPATIAL LOCALITY (Row Access)
// Excellent SRAM utilization (fewer cache misses)
for (int i = 0; i < MATRIX_SIZE; i++) {
    for (int j = 0; j < MATRIX_SIZE; j++) {
        M[i][j] = 1;
    }
}

// SCENARIO 2: LOW SPATIAL LOCALITY (Column Access)
// Poor SRAM utilization (thrashing/high misses)
for (int j = 0; j < MATRIX_SIZE; j++) {
    for (int i = 0; i < MATRIX_SIZE; i++) {
        M[i][j] = 1;
    }
}
